  const m = /^\/api\/produits\/(\d+)$/.exec(adresse.pathname);
  const p = m && trouver(Number(m[1]));
  if (p) return envoyerJSON(res, 200, p);
  envoyerJSON(res, 404, { erreur: "introuvable" });
});
